package server

import (
	"context"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	billingpb "myapp/gen/billing/v1"
	"myapp/service"
)

type BillingServer struct {
	billingpb.UnimplementedBillingServiceServer
	BillingService service.BillingService
}

func (s *BillingServer) CancelSubscription(ctx context.Context, req *billingpb.CancelSubscriptionRequest) (*billingpb.CancelSubscriptionResponse, error) {
	// BOLA: Trusts req.CustomerId from protobuf payload instead of verifying
	// against caller credentials injected into context by auth interceptor.
	err := s.BillingService.Cancel(ctx, req.GetCustomerId(), req.GetSubscriptionId())
	if err != nil {
		return nil, status.Errorf(codes.Internal, "Failed to cancel subscription: %v", err)
	}

	return &billingpb.CancelSubscriptionResponse{
		Status: "CANCELLED",
	}, nil
}

corrected_code:
package server

import (
	"context"
	"google.golang.org/grpc/codes"
	"google.golang.org/grpc/status"
	billingpb "myapp/gen/billing/v1"
	"myapp/auth"
	"myapp/service"
)

type BillingServer struct {
	billingpb.UnimplementedBillingServiceServer
	BillingService service.BillingService
}

func (s *BillingServer) CancelSubscription(ctx context.Context, req *billingpb.CancelSubscriptionRequest) (*billingpb.CancelSubscriptionResponse, error) {
	authCustomer, ok := auth.GetCustomerFromContext(ctx)
	if !ok {
		return nil, status.Error(codes.Unauthenticated, "Authentication required")
	}

	if authCustomer.ID != req.GetCustomerId() {
		return nil, status.Error(codes.PermissionDenied, "Cannot cancel subscription for another customer")
	}

	err := s.BillingService.Cancel(ctx, authCustomer.ID, req.GetSubscriptionId())
	if err != nil {
		return nil, status.Errorf(codes.Internal, "Failed to cancel subscription: %v", err)
	}

	return &billingpb.CancelSubscriptionResponse{
		Status: "CANCELLED",
	}, nil
}
